INSERT INTO "products" ("id", "seller_id", "category_id", "name", "description", "price", "stock", "status", "created_at", "is_featured", "image_url", "seller_name", "is_visible", "sold_count", "average_rating", "total_ratings") VALUES ('31', '16', '1', 'NOKIA 3210', 'The Nokia 3210 is a modernized 4G feature phone that revives the iconic 1999 classic with Y2K nostalgia. It boasts a 2.4-inch color display, a 2MP camera, and essential connectivity features like Bluetooth 5.0 and USB Type-C charging, making it the perfect device for a digital detox.', '750', '7', 'approved', '2026-05-25T05:00:46.446874', 'false', 'https://ffqhspyzvxlrvdeiwtkh.supabase.co/storage/v1/object/public/uploads/products/1779685245776-silpon.jpg', 'Bernard', 'true', '0', NULL, '0');
